\mathrm{df\text{-}metric\text{-}presentation}\vdash\;\begin{aligned}
\mathsf{Met}(\mathcal A)\leftrightarrow{}&A\ne\varnothing\land\mathsf{Fun}(D,(A\times_N A)\times_N N,\mathbb Q_c)\land\forall a,b\in A\;\mathsf{Real}(D_{ab})\\
&\land\forall a\in A\;D_{aa}=_R\widehat0\\
&\land\forall a,b\in A\;(D_{ab}=_R D_{ba}\land\widehat0\le_R D_{ab})\\
&\land\forall a,b,c\in A\;D_{ac}\le_R D_{ab}+_R D_{bc}.
\end{aligned}

\begin{aligned}
D_{ab}&\coloneqq\{\langle k,q\rangle_N:\langle\langle\langle a,b\rangle_N,k\rangle_N,q\rangle_N\in D\},\\
\forall\mathcal A\ \Phi(\mathcal A)&\;:\!\equiv\;\forall A\forall D\ \Phi(A,D),\\
\exists\mathcal A\ \Phi(\mathcal A)&\;:\!\equiv\;\exists A\exists D\ \Phi(A,D).
\end{aligned}
